struct Point { double x, y; };
auto getAxes = [](const std::vector<Point>& p) {
    std::vector<Point> axes;
    for (size_t i = 0; i < p.size(); ++i) {
        Point p1 = p[i];
        Point p2 = p[(i + 1) % p.size()];
        Point edge = {p2.x - p1.x, p2.y - p1.y};
        axes.push_back({-edge.y, edge.x});
    }
    return axes;
};

auto project = [](const std::vector<Point>& p, Point axis) {
    double min = (p[0].x * axis.x + p[0].y * axis.y);
    double max = min;
    for (size_t i = 1; i < p.size(); ++i) {
        double proj = (p[i].x * axis.x + p[i].y * axis.y);
        if (proj < min) min = proj;
        if (proj > max) max = proj;
    }
    return std::make_pair(min, max);
};

std::vector<Point> pts1, pts2;
for (const auto& v : P1.vertices) pts1.push_back({v.x(), v.y()});
for (const auto& v : P2.vertices) pts2.push_back({v.x(), v.y()});

std::vector<Point> axes1 = getAxes(pts1);
std::vector<Point> axes2 = getAxes(pts2);

auto check = [&](const std::vector<Point>& axes) {
    for (const auto& axis : axes) {
        auto proj1 = project(pts1, axis);
        auto proj2 = project(pts2, axis);
        if (proj1.second < proj2.first || proj2.second < proj1.first) {
            return false;
        }
    }
    return true;
};

if (!check(axes1)) return false;
if (!check(axes2)) return false;

return true;
